<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { api } from '../api'
import NumberSettingRow from './NumberSettingRow.vue'
import ToggleSettingRow from './ToggleSettingRow.vue'
interface Simple { temperature: number; max_tokens: number }
interface Settings { chat: { temperature: number; max_rounds: number; stage_budgets: { exploring: number; responding: number } }; solve: Simple & { max_rounds: number; max_replans: number }; research: Simple & { researching: { note_agent_mode: string; tool_timeout: number; tool_max_retries: number; paper_search_years_limit: number } }; question: Simple & { exploring: { max_iterations: number; tool_summarizer: { enabled: boolean; max_tokens: number } } }; co_writer: Simple; vision_solver: Simple; math_animator: Simple; visualize: Simple }
const props = withDefaults(defineProps<{ pending?: unknown; revision?: number; language?: string }>(), { revision: 0 })
const chinese = computed(() => (props.language || 'zh').toLowerCase().startsWith('zh'))
const tr = (zh: string, en: string) => chinese.value ? zh : en
const emit = defineEmits<{ change: [value: Settings]; loaded: [value: Settings] }>()
const settings = reactive<Settings>({ chat: { temperature: 0.7, max_rounds: 12, stage_budgets: { exploring: 4000, responding: 4000 } }, solve: { temperature: 0.7, max_tokens: 4000, max_rounds: 12, max_replans: 2 }, research: { temperature: 0.7, max_tokens: 4000, researching: { note_agent_mode: 'auto', tool_timeout: 60, tool_max_retries: 2, paper_search_years_limit: 5 } }, question: { temperature: 0.7, max_tokens: 4000, exploring: { max_iterations: 6, tool_summarizer: { enabled: true, max_tokens: 1200 } } }, co_writer: { temperature: 0.7, max_tokens: 4000 }, vision_solver: { temperature: 0.7, max_tokens: 4000 }, math_animator: { temperature: 0.7, max_tokens: 4000 }, visualize: { temperature: 0.7, max_tokens: 4000 } })
const loading = ref(true); const loaded = ref(false); const error = ref('')
let loadVersion = 0
function valid(value: unknown): value is Settings {
  if (!value || typeof value !== 'object') return false
  const row = value as Record<string, any>
  return typeof row.chat?.temperature === 'number' && typeof row.chat?.max_rounds === 'number'
    && typeof row.chat?.stage_budgets?.exploring === 'number' && typeof row.chat?.stage_budgets?.responding === 'number'
    && typeof row.solve?.max_rounds === 'number' && typeof row.solve?.max_replans === 'number'
    && Boolean(row.research?.researching && row.question?.exploring?.tool_summarizer && row.visualize && row.co_writer && row.math_animator)
}
async function load() {
  const version = ++loadVersion
  loading.value = true; loaded.value = false; error.value = ''
  try {
    const live = await api<unknown>('/api/capabilities/settings')
    if (version !== loadVersion) return
    if (!valid(live)) throw new Error(tr('后端返回了无效的能力设置结构。', 'The backend returned an unexpected capability settings payload.'))
    Object.assign(settings, (props.pending as Settings | undefined) ?? live)
    loaded.value = true
    emit('loaded', live)
  } catch (cause) { if (version === loadVersion) error.value = cause instanceof Error ? cause.message : tr('能力设置加载失败', 'Failed to load capability settings') }
  finally { if (version === loadVersion) loading.value = false }
}
onMounted(load); onUnmounted(() => { loadVersion++ }); watch(() => props.revision, load)
function changed() { if (loaded.value) emit('change', JSON.parse(JSON.stringify(settings))) }
function patchChat<K extends keyof Settings['chat']>(key: K, value: Settings['chat'][K]) { settings.chat[key] = value; changed() }
function patchStage(stage: 'exploring' | 'responding', value: number) { settings.chat.stage_budgets[stage] = value; changed() }
function patchSimple(cap: 'solve' | 'co_writer' | 'vision_solver' | 'math_animator' | 'visualize' | 'research' | 'question', value: Partial<Simple>) { Object.assign(settings[cap], value); changed() }
function patchSolve(value: Partial<Settings['solve']>) { Object.assign(settings.solve, value); changed() }
function patchResearching(value: Partial<Settings['research']['researching']>) { Object.assign(settings.research.researching, value); changed() }
function patchExploring(value: Partial<Settings['question']['exploring']>) { Object.assign(settings.question.exploring, value); changed() }
function patchSummarizer(value: Partial<Settings['question']['exploring']['tool_summarizer']>) { Object.assign(settings.question.exploring.tool_summarizer, value); changed() }
</script>
<template><div><header class="legacy-settings-page-header"><h1>{{ tr('能力', 'Capabilities') }}</h1><p>{{ tr('配置各能力的 LLM 参数与运行时选项。', 'Per-capability LLM parameters and runtime knobs.') }}</p></header><p v-if="loading" class="legacy-settings-loading">{{ tr('加载中…', 'Loading...') }}</p><div v-else-if="error" class="error" role="alert"><p>{{ tr('无法加载能力设置', "Couldn't load capability settings") }}：{{ error }}</p><button type="button" @click="load">{{ tr('重试', 'Retry') }}</button></div><template v-else-if="loaded"><section class="legacy-setting-section"><header><h2>Chat</h2><p>{{ tr('探索代理循环后进入回复阶段，各阶段分别限制每次 LLM 调用的 max_tokens。', 'Exploring agent loop followed by a respond stage. Stage budgets cap max_tokens per LLM round.') }}</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :description="tr('所有 Chat 阶段共用的采样温度。', 'Sampling temperature shared across every chat stage.')" :value="settings.chat.temperature" :min="0" :max="2" :step="0.05" float @change="patchChat('temperature', $event)" /><NumberSettingRow :title="tr('最大轮数', 'Max rounds')" :description="tr('每轮对话中探索循环的 LLM 轮次上限；没有工具调用时提前结束。', 'Hard cap on exploring-loop LLM rounds per turn. A round without tool calls ends the loop early.')" :value="settings.chat.max_rounds" :min="1" :max="50" @change="patchChat('max_rounds', $event)" /><NumberSettingRow :title="tr('探索阶段（max tokens）', 'Exploring (max tokens)')" :description="tr('每个探索循环轮次的预算，包括笔记和工具调用。', 'Budget per exploring-loop round (notes + tool calls).')" :value="settings.chat.stage_budgets.exploring" :min="256" :max="200000" :step="100" @change="patchStage('exploring', $event)" /><NumberSettingRow :title="tr('回复阶段（max tokens）', 'Responding (max tokens)')" :description="tr('最终面向用户回复的预算。', 'Budget for the final user-facing response.')" :value="settings.chat.stage_budgets.responding" :min="256" :max="200000" :step="100" @change="patchStage('responding', $event)" /></div></section><section class="legacy-setting-section"><header><h2>Solve</h2><p>{{ tr('深度解题以 plan / finish-step / replan 为主线的单代理循环。', 'Deep solve runs as one agent loop with a plan / finish-step / replan spine.') }}</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.solve.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('solve', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.solve.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('solve', { max_tokens: $event })" /><NumberSettingRow :title="tr('最大轮数', 'Max rounds')" :description="tr('一次解题轮次的全部 LLM 预算，包括规划、工具调用和收尾。', 'Total LLM-round budget for one solve turn (plan, tool calls and finishing all count).')" :value="settings.solve.max_rounds" :min="1" :max="50" @change="patchSolve({ max_rounds: $event })" /><NumberSettingRow :title="tr('最大 replan 次数', 'Max replans')" :description="tr('规划器在一次解题中可修订计划的次数。', 'How many times the planner may revise the plan within one turn.')" :value="settings.solve.max_replans" :min="0" :max="10" @change="patchSolve({ max_replans: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Question</h2><p>{{ tr('深度题目生成流程。', 'Deep question (quiz) generation pipeline.') }}</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.question.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('question', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.question.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('question', { max_tokens: $event })" /><NumberSettingRow :title="tr('探索最大迭代次数', 'Explore max iterations')" :description="tr('规划前探索循环的迭代上限。', 'Cap on the explore loop before planning.')" :value="settings.question.exploring.max_iterations" :min="1" :max="50" @change="patchExploring({ max_iterations: $event })" /><ToggleSettingRow :title="tr('启用工具结果摘要', 'Tool summarizer enabled')" :description="tr('总结较长的工具输出，减少提示词预算。', 'Summarize long tool outputs to keep the prompt budget low.')" :checked="settings.question.exploring.tool_summarizer.enabled" @change="patchSummarizer({ enabled: $event })" /><NumberSettingRow :title="tr('工具摘要（max tokens）', 'Tool summarizer (max tokens)')" :value="settings.question.exploring.tool_summarizer.max_tokens" :min="128" :max="200000" :step="100" @change="patchSummarizer({ max_tokens: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Research</h2><p>{{ tr('深度研究流程；迭代次数由聊天输入中的深度选择器控制，不在此设置。', 'Deep research pipeline. Iteration count is controlled per request via the depth selector in the chat input, not here.') }}</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.research.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('research', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.research.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('research', { max_tokens: $event })" /><NumberSettingRow :title="tr('工具超时（秒）', 'Tool timeout (s)')" :description="tr('研究阶段每个工具的墙钟超时。', 'Per-tool wall-clock timeout for the researching phase.')" :value="settings.research.researching.tool_timeout" :min="1" :max="600" @change="patchResearching({ tool_timeout: $event })" /><NumberSettingRow :title="tr('工具最大重试次数', 'Tool max retries')" :value="settings.research.researching.tool_max_retries" :min="0" :max="10" @change="patchResearching({ tool_max_retries: $event })" /><NumberSettingRow :title="tr('论文搜索年限', 'Paper search years limit')" :description="tr('论文搜索向前扫描的年数。', 'How far back paper search will scan.')" :value="settings.research.researching.paper_search_years_limit" :min="1" :max="50" @change="patchResearching({ paper_search_years_limit: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Math animator</h2><p>{{ tr('Manim 动画与图片生成流程。', 'Manim animation / image generation pipeline.') }}</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.math_animator.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('math_animator', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.math_animator.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('math_animator', { max_tokens: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Visualize</h2><p>{{ tr('SVG、图表和示意图生成循环。', 'SVG / chart / diagram generation loop.') }}</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.visualize.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('visualize', { temperature: $event })" /><NumberSettingRow title="Max tokens" :description="tr('推理模型可能将大部分预算用于内部推理；画布为空时可适当提高。', 'A reasoning model can spend most of this on internal reasoning; raise it if a canvas comes back empty.')" :value="settings.visualize.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('visualize', { max_tokens: $event })" /></div></section><section class="legacy-setting-section"><header><h2>Co-writer</h2><p>{{ tr('选区编辑与内联改写代理。', 'Selection edit / inline rewrite agent.') }}</p></header><div class="legacy-setting-section-body"><NumberSettingRow title="Temperature" :value="settings.co_writer.temperature" :min="0" :max="2" :step="0.05" float @change="patchSimple('co_writer', { temperature: $event })" /><NumberSettingRow title="Max tokens" :value="settings.co_writer.max_tokens" :min="256" :max="200000" :step="100" @change="patchSimple('co_writer', { max_tokens: $event })" /></div></section></template></div></template>
